    sub = df[mask]
    if len(sub) < 2:
        continue
    dec_first = sub['Close'].iloc[0]
    dec_last = sub['Close'].iloc[-1]
    dec_return = (dec_last / dec_first - 1) * 100
    dec_days = (sub['Date'].iloc[-1] - sub['Date'].iloc[0]).days
    dec_years = dec_days / 365.25
    dec_cagr = (dec_last / dec_first) ** (1 / dec_years) - 1 if dec_years > 0 else 0
    dec_vol = sub['Daily_Return'].dropna().std() * np.sqrt(252)
    dec_max_dd = sub['Drawdown'].min()
    dec_div = sub['Dividends'].sum()
    decade_metrics.append({
        'decade': f'{dec}s',
        'start_price': dec_first,
        'end_price': dec_last,
        'total_return': dec_return,
        'cagr': dec_cagr,
