import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import matplotlib.ticker as mticker
from matplotlib.patches import FancyBboxPatch
from io import BytesIO
import base64
import warnings
warnings.filterwarnings('ignore')

# ── Configuration ──────────────────────────────────────────────────────
plt.rcParams.update({
    'figure.facecolor': '#0d1117',
    'axes.facecolor': '#161b22',
    'axes.edgecolor': '#30363d',
    'axes.labelcolor': '#c9d1d9',
    'text.color': '#c9d1d9',
    'xtick.color': '#8b949e',
    'ytick.color': '#8b949e',
    'grid.color': '#21262d',
    'grid.alpha': 0.6,
    'font.family': 'sans-serif',
    'font.size': 10,
})

COLORS = {
    'primary': '#58a6ff',
    'green': '#3fb950',
    'red': '#f85149',
    'orange': '#d29922',
    'purple': '#bc8cff',
    'cyan': '#39d2c0',
    'white': '#f0f6fc',
    'gray': '#8b949e',
    'dark_bg': '#0d1117',
    'card_bg': '#161b22',
    'border': '#30363d',
}

# ── Load Data ──────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], utc=True)
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Decade'] = (df['Year'] // 10) * 10

# ── Compute KPIs ──────────────────────────────────────────────────────
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
cumulative_return = (last_close / first_close - 1) * 100
total_days = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days
total_years = total_days / 365.25
cagr = (last_close / first_close) ** (1 / total_years) - 1

# Daily returns & volatility
df['Daily_Return'] = df['Close'].pct_change()
daily_vol = df['Daily_Return'].dropna().std()
annualized_vol = daily_vol * np.sqrt(252)

# Max drawdown
df['Cummax'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['Cummax']) / df['Cummax']
max_dd = df['Drawdown'].min()
max_dd_date = df.loc[df['Drawdown'].idxmin(), 'Date']
max_dd_peak_date = df.loc[:df['Drawdown'].idxmin(), 'Close'].idxmax()
max_dd_peak_date = df.loc[max_dd_peak_date, 'Date']

# Total dividends
total_dividends = df['Dividends'].sum()

# All-time high / low
ath_idx = df['Close'].idxmax()
atl_idx = df['Close'].idxmin()
ath_price = df['Close'].iloc[ath_idx]
ath_date = df['Date'].iloc[ath_idx]
atl_price = df['Close'].iloc[atl_idx]
atl_date = df['Date'].iloc[atl_idx]

# ── Drawdown episodes ─────────────────────────────────────────────────
def find_drawdown_episodes(df, threshold=-0.20):
    episodes = []
    in_drawdown = False
    peak_idx = 0
    trough_idx = 0
    for i in range(1, len(df)):
        dd = df['Drawdown'].iloc[i]
        if not in_drawdown and dd < threshold:
            in_drawdown = True
            # find the peak just before this drawdown
            peak_idx = df.loc[:i, 'Close'].idxmax()
            trough_idx = i
        elif in_drawdown:
            if dd < df['Drawdown'].iloc[trough_idx]:
                trough_idx = i
            if dd >= -0.05:  # recovered to within 5%
                peak_date = df['Date'].iloc[peak_idx]
                trough_date = df['Date'].iloc[trough_idx]
                recovery_date = df['Date'].iloc[i]
                trough_val = df['Drawdown'].iloc[trough_idx]
                episodes.append({
                    'peak_date': peak_date,
                    'trough_date': trough_date,
                    'recovery_date': recovery_date,
                    'drawdown': trough_val,
                    'peak_price': df['Close'].iloc[peak_idx],
                    'trough_price': df['Close'].iloc[trough_idx],
                })
                in_drawdown = False
    # If still in drawdown at end
    if in_drawdown:
        episodes.append({
            'peak_date': df['Date'].iloc[peak_idx],
            'trough_date': df['Date'].iloc[trough_idx],
            'recovery_date': None,
            'drawdown': df['Drawdown'].iloc[trough_idx],
            'peak_price': df['Close'].iloc[peak_idx],
            'trough_price': df['Close'].iloc[trough_idx],
        })
    episodes.sort(key=lambda x: x['drawdown'])
    return episodes

dd_episodes = find_drawdown_episodes(df)

# ── Decade-by-decade metrics ──────────────────────────────────────────
decades = [1970, 1980, 1990, 2000, 2010, 2020]
decade_metrics = []
for i, dec in enumerate(decades):
    if i < len(decades) - 1:
        mask = (df['Year'] >= dec) & (df['Year'] < decades[i+1])
    else:
        mask = (df['Year'] >= dec)
    sub = df[mask]
    if len(sub) < 2:
        continue
    dec_first = sub['Close'].iloc[0]
    dec_last = sub['Close'].iloc[-1]
    dec_return = (dec_last / dec_first - 1) * 100
    dec_days = (sub['Date'].iloc[-1] - sub['Date'].iloc[0]).days
    dec_years = dec_days / 365.25
    dec_cagr = (dec_last / dec_first) ** (1 / dec_years) - 1 if dec_years > 0 else 0
    dec_vol = sub['Daily_Return'].dropna().std() * np.sqrt(252)
    dec_max_dd = sub['Drawdown'].min()
    dec_div = sub['Dividends'].sum()
    decade_metrics.append({
        'decade': f'{dec}s',
        'start_price': dec_first,
        'end_price': dec_last,
        'total_return': dec_return,
        'cagr': dec_cagr,
        'volatility': dec_vol,
        'max_drawdown': dec_max_dd,
        'total_dividends': dec_div,
    })

# ── CAGR sub-periods ─────────────────────────────────────────────────
sub_periods = [
    ('1972–1982', '1972-06-01', '1982-12-31'),
    ('1983–1999', '1983-01-01', '1999-12-31'),
    ('2000–2009', '2000-01-01', '2009-12-31'),
    ('2010–2019', '2010-01-01', '2019-12-31'),
    ('2020–2026', '2020-01-01', '2026-03-11'),
]
sub_cagrs = []
for label, start, end in sub_periods:
    mask = (df['Date'] >= pd.Timestamp(start, tz='UTC')) & (df['Date'] <= pd.Timestamp(end, tz='UTC'))
    sub = df[mask]
    if len(sub) < 2:
        continue
    s, e = sub['Close'].iloc[0], sub['Close'].iloc[-1]
    yrs = (sub['Date'].iloc[-1] - sub['Date'].iloc[0]).days / 365.25
    c = (e / s) ** (1 / yrs) - 1 if yrs > 0 else 0
    sub_cagrs.append({'period': label, 'cagr': c, 'start_price': s, 'end_price': e, 'years': yrs})

# ── Dividend history ──────────────────────────────────────────────────
div_df = df[df['Dividends'] > 0].copy()
split_df = df[df['Stock Splits'] > 0].copy()

# Annual dividend totals
df['Year_only'] = df['Date'].dt.year
annual_div = df.groupby('Year_only')['Dividends'].sum().reset_index()
annual_div.columns = ['Year', 'Total_Dividends']

# ── Volume analysis ───────────────────────────────────────────────────
vol_df = df[df['Volume'] > 0].copy()

# ── Charting helpers ──────────────────────────────────────────────────
def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor=fig.get_facecolor())
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return b64

# ── Chart 1: Long-term price trend ───────────────────────────────────
fig, ax = plt.subplots(figsize=(16, 7))
dates = df['Date']
closes = df['Close']
ax.plot(dates, closes, color=COLORS['primary'], linewidth=1.0, alpha=0.9)
ax.fill_between(dates, closes, alpha=0.08, color=COLORS['primary'])

# Mark major events
events = [
    (pd.Timestamp('1987-10-19', tz='UTC'), 'Black Monday', COLORS['red']),
    (pd.Timestamp('2000-03-24', tz='UTC'), 'Dot-com Peak', COLORS['orange']),
    (pd.Timestamp('2009-03-09', tz='UTC'), 'GFC Trough', COLORS['green']),
    (pd.Timestamp('2020-03-23', tz='UTC'), 'COVID Low', COLORS['green']),
]
for evt_date, label, color in events:
    idx = df['Date'].sub(evt_date).abs().idxmin()
    if idx < len(df):
        ax.annotate(label, xy=(df['Date'].iloc[idx], df['Close'].iloc[idx]),
                    xytext=(0, 25), textcoords='offset points',
                    fontsize=8, color=color, fontweight='bold',
                    arrowprops=dict(arrowstyle='->', color=color, lw=1.2),
                    ha='center')

ax.set_title('American Express (AXP) — Adjusted Closing Price (1972–2026)', fontsize=14, fontweight='bold', color=COLORS['white'], pad=15)
ax.set_ylabel('Price (USD, Split/Dividend Adjusted)', fontsize=11)
ax.set_yscale('log')
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:,.0f}' if x >= 1 else f'${x:.2f}'))
ax.grid(True, alpha=0.3)
ax.set_xlim(df['Date'].iloc[0], df['Date'].iloc[-1])
chart_price_trend = fig_to_base64(fig)

# ── Chart 2: Drawdown timeline ────────────────────────────────────────
fig, ax = plt.subplots(figsize=(16, 5))
ax.fill_between(df['Date'], df['Drawdown'] * 100, 0, color=COLORS['red'], alpha=0.35)
ax.plot(df['Date'], df['Drawdown'] * 100, color=COLORS['red'], linewidth=0.5, alpha=0.7)
ax.axhline(y=-20, color=COLORS['orange'], linestyle='--', linewidth=0.8, alpha=0.7, label='−20% Bear threshold')
ax.axhline(y=-50, color=COLORS['red'], linestyle='--', linewidth=0.8, alpha=0.7, label='−50% Severe drawdown')
ax.set_title('Drawdown from Peak (1972–2026)', fontsize=14, fontweight='bold', color=COLORS['white'], pad=15)
ax.set_ylabel('Drawdown (%)', fontsize=11)
ax.set_ylim(-100, 5)
ax.legend(loc='lower right', fontsize=9, facecolor=COLORS['card_bg'], edgecolor=COLORS['border'])
ax.grid(True, alpha=0.3)
chart_drawdown = fig_to_base64(fig)

# ── Chart 3: Annualized volatility rolling window ─────────────────────
fig, ax = plt.subplots(figsize=(16, 5))
window = 252
rolling_vol = df['Daily_Return'].rolling(window=window).std() * np.sqrt(252) * 100
