import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import matplotlib.ticker as mticker
from matplotlib.patches import FancyBboxPatch
from io import BytesIO
import base64
import warnings
warnings.filterwarnings('ignore')

# ── Configuration ──────────────────────────────────────────────────────
plt.rcParams.update({
    'figure.facecolor': '#0d1117',
    'axes.facecolor': '#161b22',
    'axes.edgecolor': '#30363d',
    'axes.labelcolor': '#c9d1d9',
    'text.color': '#c9d1d9',
    'xtick.color': '#8b949e',
    'ytick.color': '#8b949e',
    'grid.color': '#21262d',
    'grid.alpha': 0.6,
    'font.family': 'sans-serif',
    'font.size': 10,
})

COLORS = {
    'primary': '#58a6ff',
    'green': '#3fb950',
    'red': '#f85149',
    'orange': '#d29922',
    'purple': '#bc8cff',
    'cyan': '#39d2c0',
    'white': '#f0f6fc',
    'gray': '#8b949e',
    'dark_bg': '#0d1117',
    'card_bg': '#161b22',
    'border': '#30363d',
}

# ── Load Data ──────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], utc=True)
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Decade'] = (df['Year'] // 10) * 10

# ── Compute KPIs ──────────────────────────────────────────────────────
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
cumulative_return = (last_close / first_close - 1) * 100
total_days = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days
total_years = total_days / 365.25
cagr = (last_close / first_close) ** (1 / total_years) - 1

# Daily returns & volatility
df['Daily_Return'] = df['Close'].pct_change()
daily_vol = df['Daily_Return'].dropna().std()
annualized_vol = daily_vol * np.sqrt(252)

# Max drawdown
df['Cummax'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['Cummax']) / df['Cummax']
max_dd = df['Drawdown'].min()
max_dd_date = df.loc[df['Drawdown'].idxmin(), 'Date']
max_dd_peak_date = df.loc[:df['Drawdown'].idxmin(), 'Close'].idxmax()
max_dd_peak_date = df.loc[max_dd_peak_date, 'Date']

# Total dividends
total_dividends = df['Dividends'].sum()

# All-time high / low
ath_idx = df['Close'].idxmax()
atl_idx = df['Close'].idxmin()
ath_price = df['Close'].iloc[ath_idx]
ath_date = df['Date'].iloc[ath_idx]
atl_price = df['Close'].iloc[atl_idx]
atl_date = df['Date'].iloc[atl_idx]

# ── Drawdown episodes ─────────────────────────────────────────────────
def find_drawdown_episodes(df, threshold=-0.20):
    episodes = []
    in_drawdown = False
    peak_idx = 0
    trough_idx = 0
    for i in range(1, len(df)):
        dd = df['Drawdown'].iloc[i]
        if not in_drawdown and dd < threshold:
            in_drawdown = True
            # find the peak just before this drawdown
            peak_idx = df.loc[:i, 'Close'].idxmax()
            trough_idx = i
        elif in_drawdown:
            if dd < df['Drawdown'].iloc[trough_idx]:
                trough_idx = i
            if dd >= -0.05:  # recovered to within 5%
                peak_date = df['Date'].iloc[peak_idx]
                trough_date = df['Date'].iloc[trough_idx]
                recovery_date = df['Date'].iloc[i]
                trough_val = df['Drawdown'].iloc[trough_idx]
                episodes.append({
                    'peak_date': peak_date,
                    'trough_date': trough_date,
                    'recovery_date': recovery_date,
                    'drawdown': trough_val,
                    'peak_price': df['Close'].iloc[peak_idx],
